const lead = $input.first().json;

let dmLinkedin = '';
const desc = lead.Description || '';
const linkedinMatch = desc.match(/DM LinkedIn:\s*(https?:\/\/(?:www\.)?linkedin\.com\/in\/[^\s]+)/);
if (linkedinMatch) dmLinkedin = linkedinMatch[1];

let dmName = '';
const dmMatch = desc.match(/Decision Maker:\s*([^\u2014\n]+)/);
if (dmMatch) dmName = dmMatch[1].trim();
if (!dmName || dmName === 'Unknown') dmName = (lead.FirstName || '') + ' ' + (lead.LastName || '');

let icpRating = lead.Rating || 'Cold';

let product = 'Unknown';
const productMatch = desc.match(/Product Interest:\s*([^\n]+)/);
if (productMatch) product = productMatch[1].trim();
const prodMatch2 = desc.match(/Product:\s*([^\n]+)/);
if (product === 'Unknown' && prodMatch2) product = prodMatch2[1].trim();

return [{
  json: {
    leadId: lead.Id,
    firstName: lead.FirstName || '',
    lastName: lead.LastName || '',
    dmName,
    company: lead.Company || '',
    title: lead.Title || '',
    email: lead.Email || '',
    phone: lead.Phone || '',
    website: lead.Website || '',
    city: lead.City || '',
    state: lead.State || '',
    country: lead.Country || '',
    description: desc,
    icpRating,
    product,
    dmLinkedin
  }
}];

const lead = $('Prep Lead Info').first().json;

let linkedinProfile = 'No LinkedIn profile data available.';
try {
  const liRaw = $('Scrape DM LinkedIn').first().json;
  const liText = liRaw.data || liRaw.body || JSON.stringify(liRaw) || '';
  linkedinProfile = liText.substring(0, 4000);
} catch(e) {}

return [{
  json: {
    ...lead,
    linkedinProfile
  }
}];

