const lead = $('Merge LinkedIn Data').first().json;
const aiRaw = $input.first().json.output || $input.first().json.text || '';

let seq = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) seq = JSON.parse(m[0]);
} catch(e) {
  seq = { touch_1: { subject: 'Error', body: aiRaw, day: 1 } };
}

const t1 = seq.touch_1 || {};
const t2 = seq.touch_2 || {};
const t3 = seq.touch_3 || {};
const t4 = seq.touch_4 || {};

return [{
  json: {
    leadId: lead.leadId,
    dmName: lead.dmName,
    firstName: lead.firstName,
    lastName: lead.lastName,
    company: lead.company,
    toEmail: lead.email,
    title: lead.title,
    product: lead.product,
    icpRating: lead.icpRating,
    t1_subject: t1.subject || '',
    t1_body: t1.body || '',
    t2_subject: t2.subject || '',
    t2_body: t2.body || '',
    t3_subject: t3.subject || '',
    t3_body: t3.body || '',
    t4_subject: t4.subject || '',
    t4_body: t4.body || '',
    linkedinMessage: seq.linkedin_message || '',
    personalizationNotes: seq.personalization_notes || '',
    confidence: seq.confidence || 'low'
  }
}];

